recs.append(R(7096513,"سمر بیری اسموتھی","یہ مصروف صبحوں کے لیے ایک بہترین ناشتہ ہے۔","1","300 گرام",
["50 گرام منجمد رسبھریاں","50 گرام منجمد اسٹرابیریاں","200 ملی لیٹر بالائی اتارا ہوا دودھ","چینی سے پاک اور کیلوری سے پاک سویٹنر، ذائقے کے مطابق"],
["بیریز اور دودھ کو فوڈ پروسیسر یا بلینڈر میں ڈالیں اور ہموار اور جھاگ دار ہونے تک بلینڈ کریں، ذائقے کے مطابق میٹھا کریں اور پیش کریں۔"],
["اپنی خوراک میں پروبائیوٹکس شامل کرنے کے لیے 1 کھانے کا چمچ کم چکنائی والا زندہ دہی ڈالیں۔","آپ دوسرے پھل جیسے آم، کیلا، آڑو، نیکٹرین یا صرف ایک قسم کی بیری استعمال کر سکتے ہیں۔ اگر بہت پکے پھل استعمال کر رہے ہیں تو آپ کو سویٹنر ڈالنے کی ضرورت نہیں ہونی چاہیے۔","سمر بیریز میں کاربوہائیڈریٹس قدرتی طور پر اشنکٹبندیی پھلوں جیسے کیلا یا آم سے کم ہوتے ہیں۔","دودھ کے متبادل کے لیے بغیر میٹھے، فورٹیفائیڈ پودوں سے بنے دودھ کا استعمال کریں۔",FVH(1)],[]))
recs.append(R(7099518,"چار گرل کی ہوئی سرخ شملہ مرچ اور ٹماٹر کی سالسا","یہ مزیدار ڈپ شملہ مرچوں اور چیری ٹماٹروں سے بنایا جاتا ہے، پھر مسالوں، لہسن اور دھنیے کے ساتھ بلینڈ کیا جاتا ہے۔","6","218 گرام",
["3 سرخ شملہ مرچیں، بیج نکالی ہوئی اور چار حصوں میں کٹی ہوئی","2 سرخ پیاز، قاشوں میں کٹی ہوئی","200 گرام پکے ٹماٹر، کٹے ہوئے","1 ڈھیر والا کھانے کا چمچ ٹماٹر کا پیوری","1 چائے کا چمچ پسا ہوا زیرہ","1 چائے کا چمچ اوریگانو","چٹکی بھر کُٹی ہوئی لال مرچ (یا 1 چھوٹی تازہ مرچ، باریک کٹی ہوئی)","25 گرام دھنیا، باریک کٹا ہوا","1 گاجر، لمبی ڈنڈیوں کی شکل میں کٹی ہوئی","6 سینٹی میٹر کھیرا، لمبی ڈنڈیوں کی شکل میں کٹا ہوا","1 پیلی شملہ مرچ، لمبی ڈنڈیوں کی شکل میں کٹی ہوئی"],
["اوون کو 190°C/ گیس مارک 5 پر پہلے سے گرم کریں۔","شملہ مرچوں اور پیاز کو 25-30 منٹ روسٹ کریں، کبھی کبھی پلٹتے رہیں تاکہ یکساں پکیں۔","کوئی بھی جلا ہوا ٹکڑا نکال کر پھینک دیں۔ آدھی شملہ مرچیں اور پیاز رکھ لیں، پھر باقی آدھے کو بلینڈر میں ٹماٹر، ٹماٹر کا پیوری، زیرہ، اوریگانو اور کُٹی ہوئی لال مرچ کے ساتھ ڈالیں۔ ہموار ہونے تک بلینڈ کریں۔","باقی پیاز اور سرخ شملہ مرچ کاٹیں، پھر بلینڈ کیے ہوئے اجزاء میں تازہ دھنیے کے ساتھ ملا دیں۔ باقی اجزاء ملائیں اور سبزیوں کی ڈنڈیوں کے ساتھ پیش کریں۔"],
["آپ کسی بھی رنگ کی شملہ مرچیں استعمال کر سکتے ہیں۔ پیٹا کی پٹیوں کے ساتھ بھی مزیدار لگتا ہے۔","یہ سالسا گرل کیے ہوئے گوشت یا مچھلی کے ساتھ بھی اچھی لگتی ہے۔ یا اپنے پسندیدہ سینڈوچ یا ریپ میں تھوڑی ڈال کر دیکھیں۔",FVH(2)],[]))
recs.append(R(7100422,"چھوٹے سمر پڈنگ","کم چکنائی والا، لیکن لذیذ پڈنگ۔","4","185 گرام",
["8–10 قتلے باریک کٹی سفید ڈبل روٹی، کنارے ہٹائے ہوئے (240 گرام)","500 گرام کا تھیلا منجمد ملے جلے گرمیوں کے پھل","مصنوعی سویٹنر، ذائقے کے مطابق"],
["4 چائے کے کپ، ڈاریول یا انفرادی چھوٹے پڈنگ بیسن کے سانچوں پر کلنگ فلم لگا دیں۔","ڈبل روٹی سے 4 x 5 سینٹی میٹر کے دائرے کاٹیں اور سانچوں کی تہہ میں دبا دیں۔ ڈبل روٹی کے 4 بڑے دائرے کاٹیں (اتنے بڑے کہ ڈھکن کی طرح ڈھانپ سکیں)۔ باقی ڈبل روٹی کو پٹیوں میں کاٹیں اور سانچوں کے اطراف پر لگا دیں۔","گرمیوں کے پھلوں کو سوس پین میں ڈالیں، اور ہلکا گرم کریں یہاں تک کہ پگھل جائیں۔ ذائقے کے مطابق میٹھا کریں۔ پھلوں کا پانی نکالیں اور رس رکھ لیں۔","پھلوں کا آمیزہ ڈبل روٹی لگے ہوئے کپوں میں تقسیم کریں، پھر اوپر ڈبل روٹی کے \"ڈھکن\" رکھ دیں۔ محفوظ کیا ہوا رس اوپر ڈالیں، پیش کرنے کے لیے تھوڑا رس بچا کر رکھیں۔","کپوں کو کلنگ فلم سے ڈھانپیں، اوپر چھوٹی پلیٹ رکھیں اور بھاری وزن سے دبا دیں۔ چند گھنٹوں کے لیے فریج میں رکھیں۔","پلیٹوں پر الٹ دیں اور محفوظ کیا ہوا رس باقی ڈبل روٹی کو ڈھانپنے کے لیے استعمال کریں۔","ایک چمچ لائٹ کریم فریش یا دہی کے ساتھ پیش کریں۔"],
["پڈنگز کے ساتھ پیش کرنے کے لیے چند بیریز رکھ لیں، یا اوپر تازہ رسبھریاں یا بلیک بیریز ڈالیں۔","بہترین نتائج کے لیے پڈنگز کو رات بھر فریج میں رہنے دیں تاکہ ڈبل روٹی پھلوں کے رس میں مکمل بھیگ جائے۔",FVH(1)],[]))
